using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Text;using System.Web.Script.Serialization;using DiscUtils;using DiscUtils.Ext;using DiscUtils.Streams;
namespace FileCompass {
 public sealed class ExtVolume {public long Offset,Length;public string Id,Label,Error;public override string ToString(){return Label+(Error==null?"":" · "+Error);}}
 public sealed class ExtEntry {public string Name{get;set;}public string Path{get;set;}public string Kind{get;set;}public long Size{get;set;}public DateTime Modified{get;set;}public bool Directory{get;set;}public bool Readable{get;set;}public bool Parent{get;set;}public long Inode{get;set;}public string DisplaySize{get{return Parent||Directory||!Readable?"":Size.ToString("N0");}}public string DisplayDate{get{return Parent?"":Modified.ToString("yyyy-MM-dd HH:mm");}}}
 public sealed class ExtRequest {public string Action,Path,Target;public string[] Paths;public ExtSource Source;public ExtVolume Volume;}
 public sealed class ExtResponse {public string Error;public ExtVolume[] Volumes;public ExtEntry[] Entries;public int Completed,Skipped;public long Bytes;public string[] Warnings;}
 internal static class ExtReader {
  static JavaScriptSerializer Json{get{return new JavaScriptSerializer{MaxJsonLength=16*1024*1024};}}
  internal static string Normal(string path){if(String.IsNullOrEmpty(path)||path=="/")return "/";if(path.Length>8192||path.IndexOf('\0')>=0||path.IndexOf('\\')>=0)throw new IOException(L.Text("ext.invalidPath"));var parts=path.Split(new[]{'/'},StringSplitOptions.RemoveEmptyEntries);if(parts.Any(x=>x=="."||x==".."||x.Length>255))throw new IOException(L.Text("ext.invalidPath"));return "/"+String.Join("/",parts);}
  internal static string Join(string path,string name){if(String.IsNullOrEmpty(name)||name.IndexOfAny(new[]{'/','\\','\0'})>=0||name=="."||name=="..")throw new IOException(L.Text("ext.invalidPath"));return Normal(path.TrimEnd('/')+"/"+name);}
  static byte[] Header(Stream stream){stream.Position=1024;var b=new byte[1024];int n=0,k;while(n<b.Length&&(k=stream.Read(b,n,b.Length-n))>0)n+=k;if(n!=b.Length||BitConverter.ToUInt16(b,56)!=0xef53)throw new IOException(L.Text("ext.noExt"));return b;}
  internal static string Validate(Stream stream){if(stream.Length<2048)throw new IOException(L.Text("ext.noExt"));var h=Header(stream);uint incompatible=BitConverter.ToUInt32(h,96),ro=BitConverter.ToUInt32(h,100);if((incompatible&4)!=0||(BitConverter.ToUInt16(h,58)&3)!=1)throw new IOException(L.Text("ext.dirty"));if((incompatible&~(2u|0x40u|0x80u|0x200u|0x2000u))!=0||(ro&(0x200u|0x8000u|0x10000u))!=0)throw new IOException(L.Text("ext.features")+" 0x"+incompatible.ToString("x")+" / 0x"+ro.ToString("x"));int log=BitConverter.ToInt32(h,24);if(log<0||log>6)throw new IOException(L.Text("ext.invalidFs"));long block=1024L<<log;ulong blocks=BitConverter.ToUInt32(h,4);if((incompatible&0x80)!=0)blocks|=(ulong)BitConverter.ToUInt32(h,336)<<32;uint per=BitConverter.ToUInt32(h,32),inodes=BitConverter.ToUInt32(h,40);int inode=BitConverter.ToUInt16(h,88);int descriptor=(incompatible&0x80)!=0?BitConverter.ToUInt16(h,254):32;if(blocks==0||blocks>(ulong)(stream.Length/block)||per==0||inodes==0||inode<128||inode>block||descriptor<32||descriptor>block||(blocks+per-1)/per>1048576||(blocks+per-1)/per*(ulong)descriptor>64*1024*1024)throw new IOException(L.Text("ext.invalidFs"));return BitConverter.ToString(h,104,16);}
  static bool Magic(Stream stream){if(stream.Length<2048)return false;try{Header(stream);return true;}catch(EndOfStreamException){return false;}catch(IOException){return false;}}
  internal static ExtVolume[] Scan(ExtSource source){using(var stream=ExtDiskStream.Open(source)){int sector=stream is ExtDiskStream?((ExtDiskStream)stream).Sector:source.Sector>0?source.Sector:512;if(!source.Physical&&stream.Length>=4104){stream.Position=4096;var signature=new byte[8];if(stream.Read(signature,0,8)==8&&Encoding.ASCII.GetString(signature)=="EFI PART")sector=4096;}var candidates=new List<ExtVolume>();if(Magic(stream))candidates.Add(new ExtVolume{Offset=0,Length=stream.Length});else{stream.Position=0;using(var disk=new DiscUtils.Raw.Disk(stream,Ownership.None,Geometry.FromCapacity(stream.Length,sector))){if(!disk.IsPartitioned)return new ExtVolume[0];int n=0;foreach(var partition in disk.Partitions.Partitions){if(++n>128)throw new IOException(L.Text("ext.limit"));long offset=checked(partition.FirstSector*(long)(sector)),length=checked(partition.SectorCount*(long)(sector));using(var slice=new ExtSlice(stream,offset,length))if(Magic(slice))candidates.Add(new ExtVolume{Offset=offset,Length=length});}}}foreach(var volume in candidates)using(var slice=new ExtSlice(stream,volume.Offset,volume.Length)){try{volume.Id=Validate(slice);using(var fs=new ExtFileSystem(slice)){if(fs.CanWrite)throw new IOException(L.Text("ext.readOnlyRequired"));volume.Label=String.IsNullOrWhiteSpace(fs.VolumeLabel)?"ext":fs.VolumeLabel;}volume.Label+=" · "+(volume.Length/1073741824.0).ToString("0.##")+" GiB · "+volume.Offset;}catch(Exception ex){volume.Error=ex.Message;volume.Label="ext · "+volume.Offset;}}return candidates.ToArray();}}
  internal sealed class Session:IDisposable {Stream source;ExtSlice slice;internal ExtFileSystem FileSystem;internal Session(ExtRequest request){try{source=ExtDiskStream.Open(request.Source);slice=new ExtSlice(source,request.Volume.Offset,request.Volume.Length);if(Validate(slice)!=request.Volume.Id)throw new IOException(L.Text("ext.changed"));FileSystem=new ExtFileSystem(slice);if(FileSystem.CanWrite)throw new IOException(L.Text("ext.readOnlyRequired"));}catch{Dispose();throw;}}public void Dispose(){if(FileSystem!=null)FileSystem.Dispose();if(slice!=null)slice.Dispose();if(source!=null)source.Dispose();}}
  internal static ExtEntry[] List(ExtFileSystem fs,string path){return ExtMetadata.List(fs,Normal(path)).OrderByDescending(x=>x.Directory).ThenBy(x=>x.Name,StringComparer.Ordinal).ToArray();}
  internal static void WindowsName(string name){if(String.IsNullOrWhiteSpace(name)||name.EndsWith(".")||name.EndsWith(" ")||name.IndexOfAny(System.IO.Path.GetInvalidFileNameChars())>=0||name=="."||name==".."||System.Text.RegularExpressions.Regex.IsMatch(name,@"^(CON|PRN|AUX|NUL|COM[0-9]|LPT[0-9])(?:\.|$)",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new IOException(L.Text("ext.windowsName")+" "+name);}
  static void CopyFile(ExtFileSystem fs,string path,string target,long max,ExtResponse response){var type=ExtMetadata.Read(fs,path);if(!type.Readable||type.Directory)throw new IOException(L.Text("ext.special"));long expected=type.Size;if(expected<0||expected>max)throw new IOException(L.Text("ext.previewLimit"));PathSafety.RejectLinks(target);string part=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(target),".filecompass-ext-"+Guid.NewGuid().ToString("N")+".partial");try{using(PathSafety.LockAncestors(target)){using(var input=fs.OpenFile(path,FileMode.Open,FileAccess.Read))using(var output=new FileStream(part,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var buffer=new byte[1024*1024];long remaining=expected;while(remaining>0){int got=input.Read(buffer,0,(int)Math.Min(buffer.Length,remaining));if(got<=0)throw new EndOfStreamException();output.Write(buffer,0,got);remaining-=got;}output.Flush(true);}AttachmentSecurity.MarkInternet(part);if(File.Exists(target)||Directory.Exists(target))throw new IOException(L.Text("ext.collision"));File.Move(part,target);response.Completed++;response.Bytes+=expected;}}finally{if(File.Exists(part))File.Delete(part);}}
  static void Export(ExtFileSystem fs,string path,string target,ExtResponse response,HashSet<long> visited,List<string> warnings,int depth,ref int count){if(depth>64||++count>100000)throw new IOException(L.Text("ext.limit"));var type=ExtMetadata.Read(fs,path);if(type.Directory){if(!visited.Add(type.Inode)){response.Skipped++;return;}PathSafety.RejectLinks(target);Directory.CreateDirectory(target);foreach(var entry in List(fs,path)){try{WindowsName(entry.Name);if(!entry.Readable){response.Skipped++;continue;}Export(fs,entry.Path,System.IO.Path.Combine(target,entry.Name),response,visited,warnings,depth+1,ref count);}catch(Exception ex){response.Skipped++;if(warnings.Count<50)warnings.Add(entry.Name+": "+ex.Message);}}}else if(type.Readable)CopyFile(fs,path,target,Int64.MaxValue,response);else response.Skipped++;}
  internal static ExtResponse Run(ExtRequest request){if(request==null||request.Source==null)throw new IOException(L.Text("ext.invalidRequest"));if(request.Action=="scan")return new ExtResponse{Volumes=Scan(request.Source)};if(request.Volume==null)throw new IOException(L.Text("ext.missingVolume"));using(var session=new Session(request)){var fs=session.FileSystem;var response=new ExtResponse();if(request.Action=="list")response.Entries=List(fs,request.Path);else if(request.Action=="preview")CopyFile(fs,Normal(request.Path),request.Target,64*1024*1024,response);else if(request.Action=="export"){if(request.Paths==null||request.Paths.Length==0||request.Paths.Length>20000)throw new IOException(L.Text("ext.limit"));string target=System.IO.Path.GetFullPath(request.Target);if(File.Exists(target)||Directory.Exists(target))throw new IOException(L.Text("ext.collision"));PathSafety.RejectLinks(target);EnsureOtherDisk(request.Source,target);Directory.CreateDirectory(target);var warnings=new List<string>();int count=0;foreach(string selected in request.Paths){string path=Normal(selected);string name=path.Substring(path.LastIndexOf('/')+1);try{WindowsName(name);Export(fs,path,System.IO.Path.Combine(target,name),response,new HashSet<long>(),warnings,0,ref count);}catch(Exception ex){response.Skipped++;if(warnings.Count<50)warnings.Add(path+": "+ex.Message);}}response.Warnings=warnings.ToArray();}else throw new IOException(L.Text("ext.unsupportedRequest"));return response;}}
  static void EnsureOtherDisk(ExtSource source,string target){if(!source.Physical)return;string root=System.IO.Path.GetPathRoot(target);if(root==null||root.Length!=3||root[1]!=':')throw new IOException(L.Text("ext.localTarget"));uint destination=ExtDiskStream.DiskNumber(root);string device=@"\\.\PHYSICALDRIVE"+destination;if(String.Equals(device,source.Device,StringComparison.OrdinalIgnoreCase))throw new IOException(L.Text("ext.sourceTarget"));}
  internal static int Worker(string input,string output){var result=new ExtResponse();try{if(new FileInfo(input).Length>1024*1024)throw new IOException(L.Text("media.requestLimit"));result=Run(Json.Deserialize<ExtRequest>(File.ReadAllText(input)));}catch(Exception ex){result.Error=ex.GetBaseException().Message;}File.WriteAllText(output,Json.Serialize(result),new UTF8Encoding(false));return result.Error==null?0:1;}
  internal static void CleanupPartials(string root){if(!Directory.Exists(root))return;var pending=new Stack<string>();pending.Push(Path.GetFullPath(root));int count=0;while(pending.Count>0&&++count<=100000){string directory=pending.Pop();using(PathSafety.LockAncestors(System.IO.Path.Combine(directory,".guard"))){PathSafety.RejectLinks(directory);foreach(string file in Directory.GetFiles(directory,".filecompass-ext-*.partial")){if(!System.Text.RegularExpressions.Regex.IsMatch(System.IO.Path.GetFileName(file),@"^\.filecompass-ext-[0-9a-f]{32}\.partial$"))continue;PathSafety.RejectLinks(file);File.Delete(file);}foreach(string child in Directory.GetDirectories(directory)){PathSafety.RejectLinks(child);pending.Push(child);}}}}
  internal static ExtResponse Call(ExtRequest request,CancellationToken token){using(var lease=ExtIoGate.Enter(request,token))return CallCore(request,lease.Token);}
  static ExtResponse CallCore(ExtRequest request,CancellationToken token){bool existed=request.Action=="export"&&Directory.Exists(request.Target);using(var temp=new ArchiveTemp(System.IO.Path.Combine(AppPaths.ConfigDirectory,"ext-workers")))using(var job=new ArchiveProcessJob(1024)){string input=System.IO.Path.Combine(temp.Path,"request.json"),output=System.IO.Path.Combine(temp.Path,"response.json");File.WriteAllText(input,Json.Serialize(request));using(var process=new Process{StartInfo=new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--ext-worker "+SshTerminal.QuoteWindowsArgument(input)+" "+SshTerminal.QuoteWindowsArgument(output)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden}}){process.Start();try{job.Assign(process);var clock=Stopwatch.StartNew();while(!process.WaitForExit(50)){token.ThrowIfCancellationRequested();if(clock.Elapsed.TotalSeconds>(request.Action=="export"?28800:45))throw new IOException(L.Text("ext.timeout"));}token.ThrowIfCancellationRequested();if(!File.Exists(output)||new FileInfo(output).Length>16*1024*1024)throw new IOException(L.Text("ext.workerFailed"));var response=Json.Deserialize<ExtResponse>(File.ReadAllText(output));if(response==null||response.Error!=null)throw new IOException(response==null?L.Text("ext.workerFailed"):response.Error);return response;}finally{if(!process.HasExited){try{process.Kill();process.WaitForExit(3000);}catch(InvalidOperationException){}}if(request.Action=="export"&&!existed){try{CleanupPartials(request.Target);}catch(IOException){}catch(UnauthorizedAccessException){}}}}}}
 }
